#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "sparse.h"
#include "vector.h"
#include "precond.h"
#include "solvers.h"
#include "eigen.h"

static const char *get_opt(int argc, char **argv, const char *name)
{
    for (int i = 0; i < argc - 1; i++) {
        if (strcmp(argv[i], name) == 0) return argv[i+1];
    }
    return NULL;
}

static int parse_int(const char *s, int *out)
{
    char *end;
    long v = strtol(s, &end, 10);
    if (end == s || *end != '\0' || v < 1) return -1;
    *out = (int)v;
    return 0;
}

static int parse_double(const char *s, double *out)
{
    char *end;
    double v = strtod(s, &end);
    if (end == s) return -1;
    *out = v;
    return 0;
}

static void init_random_vector(double *v, int n)
{
    srand(42);
    for (int i = 0; i < n; i++) v[i] = (double)rand() / (double)RAND_MAX;
    double nrm = vec_norm2(v, n);
    if (nrm > 0.0) {
        for (int i = 0; i < n; i++) v[i] /= nrm;
    } else {
        v[0] = 1.0;
    }
}

static SolveResult *solve_linear_system(const CSRMatrix *A, const double *b,
                                       const char *solver, const char *precond,
                                       double tol, int maxiter, int restart,
                                       double omega, int *fail)
{
    Precond *P = precond_create(A, precond, omega);
    if (!P) {
        *fail = 1;
        return NULL;
    }

    SolveResult *res = NULL;
    if (strcmp(solver, "cg") == 0) {
        res = cg_solve(A, b, NULL, tol, maxiter, P);
    } else if (strcmp(solver, "gmres") == 0) {
        res = gmres_solve(A, b, NULL, tol, maxiter, restart, P);
    } else {
        *fail = 2;
    }

    precond_destroy(P);
    if (!res) *fail = 1;
    return res;
}

static CSRMatrix *make_shifted_matrix(const CSRMatrix *A, double sigma)
{
    CSRMatrix *S = csr_create(A->rows, A->cols, A->nnz);
    if (!S) return NULL;
    for (int i = 0; i <= A->rows; i++) S->row_ptr[i] = A->row_ptr[i];
    for (int k = 0; k < A->nnz; k++) S->col_indices[k] = A->col_indices[k];
    for (int i = 0; i < A->rows; i++) {
        for (int k = A->row_ptr[i]; k < A->row_ptr[i+1]; k++) {
            S->values[k] = A->values[k];
            if (A->col_indices[k] == i) S->values[k] -= sigma;
        }
    }
    return S;
}

int cmd_eigenvalue(int argc, char **argv)
{
    const char *input = get_opt(argc, argv, "--input");
    const char *method_s = get_opt(argc, argv, "--method");
    const char *shift_s = get_opt(argc, argv, "--shift");
    const char *tol_s = get_opt(argc, argv, "--tol");
    const char *maxiter_s = get_opt(argc, argv, "--maxiter");
    const char *solver = get_opt(argc, argv, "--solver");
    const char *precond = get_opt(argc, argv, "--precond");
    const char *restart_s = get_opt(argc, argv, "--restart");
    const char *omega_s = get_opt(argc, argv, "--ssor-omega");
    const char *solver_tol_s = get_opt(argc, argv, "--solver-tol");
    const char *solver_maxiter_s = get_opt(argc, argv, "--solver-maxiter");
    const char *eigvec_output = get_opt(argc, argv, "--eigvec-output");

    if (!input || !method_s || !tol_s || !maxiter_s || !solver || !precond) {
        fprintf(stderr, "Error: missing required arguments for eigenvalue\n");
        return 1;
    }

    int method;
    if (strcmp(method_s, "power") == 0) method = 0;
    else if (strcmp(method_s, "inverse") == 0) method = 1;
    else if (strcmp(method_s, "shifted-inverse") == 0) method = 2;
    else {
        fprintf(stderr, "Error: unknown method '%s'\n", method_s);
        return 1;
    }

    double sigma = 0.0;
    if (method == 2) {
        if (!shift_s) {
            fprintf(stderr, "Error: --shift is required for shifted-inverse\n");
            return 1;
        }
        if (parse_double(shift_s, &sigma) != 0) {
            fprintf(stderr, "Error: invalid shift '%s'\n", shift_s);
            return 1;
        }
    }

    double tol, omega = 1.0, solver_tol = 1e-12;
    int maxiter, restart = 30, solver_maxiter = 1000;

    if (parse_double(tol_s, &tol) != 0 || tol <= 0.0) {
        fprintf(stderr, "Error: invalid tol '%s'\n", tol_s);
        return 1;
    }
    if (parse_int(maxiter_s, &maxiter) != 0) {
        fprintf(stderr, "Error: invalid maxiter '%s'\n", maxiter_s);
        return 1;
    }
    if (strcmp(solver, "cg") != 0 && strcmp(solver, "gmres") != 0) {
        fprintf(stderr, "Error: unknown solver '%s'\n", solver);
        return 1;
    }
    if (strcmp(precond, "none") != 0 && strcmp(precond, "jacobi") != 0 &&
        strcmp(precond, "ilu0") != 0 && strcmp(precond, "ssor") != 0) {
        fprintf(stderr, "Error: unknown preconditioner '%s'\n", precond);
        return 1;
    }
    if (omega_s) {
        if (parse_double(omega_s, &omega) != 0 || !(omega > 0.0 && omega < 2.0)) {
            fprintf(stderr, "error: ssor-omega must be in (0,2)\n");
            return 1;
        }
    }
    if (restart_s && parse_int(restart_s, &restart) != 0) {
        fprintf(stderr, "Error: invalid restart '%s'\n", restart_s);
        return 1;
    }
    if (solver_tol_s && (parse_double(solver_tol_s, &solver_tol) != 0 || solver_tol <= 0.0)) {
        fprintf(stderr, "Error: invalid solver-tol '%s'\n", solver_tol_s);
        return 1;
    }
    if (solver_maxiter_s && parse_int(solver_maxiter_s, &solver_maxiter) != 0) {
        fprintf(stderr, "Error: invalid solver-maxiter '%s'\n", solver_maxiter_s);
        return 1;
    }

    CSRMatrix *A = csr_read_mm(input);
    if (!A) {
        fprintf(stderr, "Error: cannot read sparse matrix from '%s'\n", input);
        return 1;
    }
    if (A->rows != A->cols) {
        fprintf(stderr, "Error: eigenvalue requires a square matrix\n");
        csr_destroy(A);
        return 1;
    }

    int n = A->rows;
    double *v = vec_create(n);
    double *w = vec_create(n);
    double *Av = vec_create(n);
    if (!v || !w || !Av) {
        fprintf(stderr, "Error: allocation failed\n");
        free(v); free(w); free(Av);
        csr_destroy(A);
        return 1;
    }

    init_random_vector(v, n);

    int converged = 0;
    int iterations = 0;
    double eigenvalue = NAN;
    double prev_lambda = NAN;
    CSRMatrix *S = NULL;
    const CSRMatrix *OpA = A;

    if (method == 2) {
        S = make_shifted_matrix(A, sigma);
        if (!S) {
            fprintf(stderr, "Error: allocation failed\n");
            free(v); free(w); free(Av);
            csr_destroy(A);
            return 1;
        }
        OpA = S;
    }

    for (int iter = 0; iter < maxiter; iter++) {
        if (method == 0) {
            csr_spmv(A, v, w);
            double nrm = vec_norm2(w, n);
            if (nrm < 1e-300) {
                eigenvalue = 0.0;
                break;
            }
            for (int i = 0; i < n; i++) w[i] /= nrm;
            csr_spmv(A, w, Av);
            eigenvalue = vec_dot(w, Av, n);
            memcpy(v, w, n * sizeof(double));
        } else {
            int fail = 0;
            SolveResult *res = solve_linear_system(OpA, v, solver, precond, solver_tol, solver_maxiter, restart, omega, &fail);
            if (!res || !res->converged || fail) {
                eigenvalue = NAN;
                if (res) solve_result_destroy(res);
                break;
            }
            double nrm = vec_norm2(res->x, n);
            if (nrm < 1e-300) {
                eigenvalue = NAN;
                solve_result_destroy(res);
                break;
            }
            for (int i = 0; i < n; i++) w[i] = res->x[i] / nrm;
            csr_spmv(OpA, w, Av);
            double rq = vec_dot(w, Av, n);
            if (fabs(rq) < 1e-300) {
                eigenvalue = NAN;
                solve_result_destroy(res);
                break;
            }
            if (method == 1) {
                eigenvalue = 1.0 / rq;
            } else {
                eigenvalue = sigma + 1.0 / rq;
            }
            memcpy(v, w, n * sizeof(double));
            solve_result_destroy(res);
        }

        iterations = iter + 1;
        if (!isnan(prev_lambda) && fabs(eigenvalue) > 0.0) {
            if (fabs(eigenvalue - prev_lambda) / fabs(eigenvalue) < tol) {
                converged = 1;
                break;
            }
        }
        prev_lambda = eigenvalue;
    }

    if (!isnan(eigenvalue)) {
        csr_spmv(A, v, Av);
        double Avn = vec_norm2(Av, n);
        double vn = vec_norm2(v, n);
        if (vn > 0.0) {
            for (int i = 0; i < n; i++) v[i] /= vn;
            for (int i = 0; i < n; i++) Av[i] /= vn;
        }
    }

    printf("method: %s\n", method_s);
    printf("converged: %s\n", converged ? "yes" : "no");
    printf("iterations: %d\n", iterations);
    printf("eigenvalue: %.15e\n", isnan(eigenvalue) ? eigenvalue : eigenvalue);
    if (method == 2) {
        printf("shift: %.15e\n", sigma);
    }

    double resnorm = NAN;
    if (!isnan(eigenvalue)) {
        csr_spmv(A, v, Av);
        double lambda = eigenvalue;
        for (int i = 0; i < n; i++) w[i] = Av[i] - lambda * v[i];
        double num = vec_norm2(w, n);
        double vn = vec_norm2(v, n);
        if (fabs(lambda) == 0.0) {
            resnorm = INFINITY;
        } else if (vn > 0.0) {
            resnorm = num / (fabs(lambda) * vn);
        } else {
            resnorm = INFINITY;
        }
    } else {
        resnorm = NAN;
    }
    printf("eigenvector_residual: %.15e\n", resnorm);

    if (eigvec_output && !isnan(eigenvalue)) {
        if (vec_write_mm_array(v, n, eigvec_output) != 0) {
            fprintf(stderr, "Error: cannot write eigenvector to '%s'\n", eigvec_output);
        }
    }

    free(v); free(w); free(Av);
    if (S) csr_destroy(S);
    csr_destroy(A);
    return 0;
}
